try {
  const body = $input.item.json.body || {};
  const target_type = body.target_type === 'brand' ? 'brand' : 'influencer';
  const scrape_mode = body.scrape_mode === 'refresh' ? 'refresh' : 'deep';
  // Window: influencer deep=90d, refresh=7d; brand deep=30d (lighter), refresh=7d
  let window_days;
  if (scrape_mode === 'refresh') window_days = 7;
  else window_days = target_type === 'brand' ? 30 : 90;
  const results_limit = target_type === 'brand' ? 40 : 90;
  return { json: {
    username: (body.username || '').trim().toLowerCase().replace(/^@/, ''),
    target_type, scrape_mode, window_days, results_limit
  } };
} catch (e) { return { json: { error: e.message } }; }

const posts = $input.all().map(item => item.json);
const input = $('Parse Input').item.json;
const isInf = input.target_type === 'influencer';
const handle = input.username;

const normType = (t, pt) => { const tt = (t||'').toLowerCase(); if (pt === 'clips') return 'reel'; if (tt === 'sidecar') return 'carousel'; if (['image','video','carousel','reel','story'].includes(tt)) return tt; return 'image'; };

const postsForDb = posts.map(p => ({
  ig_post_id: p.id || p.shortCode,
  shortcode: p.shortCode || p.id,
  permalink: p.url || ('https://www.instagram.com/p/' + p.shortCode + '/'),
  type: normType(p.type, p.productType),
  posted_at: p.timestamp,
  caption: (p.caption || '').substring(0, 5000),
  likes_count: p.likesCount || 0,
  comments_count: p.commentsCount || 0,
  views_count: p.videoPlayCount || p.videoViewCount || 0,
  hashtags: p.hashtags && p.hashtags.length ? p.hashtags : ((p.caption || '').match(/#\w+/g) || []),
  mentions: p.mentions && p.mentions.length ? p.mentions : ((p.caption || '').match(/@\w+/g) || []),
  brand_tags: (p.taggedUsers || []).map(u => ({ username: u.username, full_name: u.full_name })),
  has_commercial_intent: /(?:#ad|#sponsored|#collab|#partnership|#gifted|paid partnership)/i.test(p.caption || ''),
  has_cta: /(?:link in bio|dm to|order now|book now|shop now|use code|discount|promo)/i.test(p.caption || '')
}));

const postsForClaude = posts.map(p => ({
  shortcode: p.shortCode,
  caption: (p.caption || '').substring(0, 1000),
  likes: p.likesCount,
  comments: p.commentsCount,
  views: p.videoPlayCount || p.videoViewCount || 0,
  type: p.type,
  product_type: p.productType,
  date: p.timestamp,
  mentions: p.mentions && p.mentions.length ? p.mentions : ((p.caption || '').match(/@\w+/g) || []),
  hashtags: p.hashtags && p.hashtags.length ? p.hashtags : ((p.caption || '').match(/#\w+/g) || []),
  tagged_usernames: (p.taggedUsers || []).map(u => u.username)
}));

const subjectType = isInf ? 'creator/influencer' : 'brand';
const taskInstruction = isInf
  ? 'For each post, detect brand collabs (#ad, #sponsored, @brand mentions, tagged brands) AND extract caption intelligence (commercial intent, CTA, product category, sales funnel stage, content theme).'
  : 'Detect WHICH INFLUENCERS this brand has worked with (look at @-tags, mentions, #collab/#ad/#gifted hashtags, tagged users that look like creator profiles).';

const enumGuide = isInf ? `\n\nENUM CONSTRAINTS — you MUST use exactly one of these values (or null):\n- intent_type: "promotional" | "informational" | "personal" | "entertainment" | "educational"\n- intent_strength: "strong" | "medium" | "weak"\n- collaboration_type: "paid_post" | "gifted" | "ambassador" | "giveaway" | "organic_mention" | "none"\n- sales_funnel_stage: "awareness" | "consideration" | "purchase" | "retention"\n\nOther fields (cta_type, product_category, content_theme, emotion_type) are free-text (1-3 words, snake_case).\n` : '';

const jsonTemplate = isInf
  ? '{"collaborations": [{"brand_name": "", "brand_instagram": "", "collab_type": "", "post_shortcode": "", "detected_signals": [], "confidence": "high|medium|low"}], "caption_insights": [{"post_shortcode": "", "brand_usernames": [], "commercial_intent": false, "intent_type": "", "intent_strength": "", "cta_present": false, "cta_type": "", "has_link": false, "has_discount": false, "has_promo_code": false, "product_category": "", "collaboration_type": "", "sales_funnel_stage": "", "content_theme": "", "emotion_type": ""}], "collab_count_90d": 0, "top_brand_partners": []}'
  : '{"influencer_collabs": [{"influencer_handle": "", "post_shortcode": "", "post_url": "", "post_date": "", "collab_type": "", "detected_signals": [], "confidence": ""}], "total_collabs": 0, "unique_influencer_count": 0, "marketing_intensity": "high|medium|low"}';

const claudePrompt = 'You are an influencer marketing analyst. Subject is a ' + subjectType + ': @' + handle + '. Analyse posts.\n\nPosts: ' + JSON.stringify(postsForClaude) + '\n\n' + taskInstruction + enumGuide + '\n\nReturn ONLY valid JSON:\n' + jsonTemplate;

const claudeBody = {
  model: 'claude-sonnet-4-20250514',
  max_tokens: 8192,
  messages: [{ role: 'user', content: claudePrompt }]
};
return { json: {
  is_influencer: isInf,
  handle,
  posts_for_db: postsForDb,
  claude_body: claudeBody,
  post_count: posts.length
} };

let data = {};
try {
  const txt = ($input.item.json.content && $input.item.json.content[0] && $input.item.json.content[0].text) || '';
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) data = JSON.parse(m[0]);
} catch (e) {}
const tp = $('Transform Posts').item.json;

const ALLOWED = {
  intent_type: new Set(['promotional','informational','personal','entertainment','educational']),
  intent_strength: new Set(['strong','medium','weak']),
  collaboration_type: new Set(['paid_post','gifted','ambassador','giveaway','organic_mention','none']),
  sales_funnel_stage: new Set(['awareness','consideration','purchase','retention'])
};
const norm = (field, raw) => {
  if (raw === null || raw === undefined || raw === '') return null;
  const v = String(raw).trim().toLowerCase().replace(/[\s-]+/g, '_');
  return ALLOWED[field].has(v) ? v : null;
};

if (tp.is_influencer) {
  const collabs = (data.collaborations || []).filter(c => c.post_shortcode).map(c => ({
    post_shortcode: c.post_shortcode,
    brand_name: c.brand_name || null,
    brand_instagram: c.brand_instagram || null,
    collab_type: c.collab_type || null,
    detected_signals: c.detected_signals || [],
    confidence: c.confidence || 'low'
  }));
  const insights = (data.caption_insights || []).filter(c => c.post_shortcode).map(c => ({
    post_shortcode: c.post_shortcode,
    brand_usernames: c.brand_usernames || [],
    commercial_intent: !!c.commercial_intent,
    intent_type: norm('intent_type', c.intent_type),
    intent_strength: norm('intent_strength', c.intent_strength),
    cta_present: !!c.cta_present,
    cta_type: c.cta_type || null,
    has_link: !!c.has_link,
    has_discount: !!c.has_discount,
    has_promo_code: !!c.has_promo_code,
    product_category: c.product_category || null,
    collaboration_type: norm('collaboration_type', c.collaboration_type),
    sales_funnel_stage: norm('sales_funnel_stage', c.sales_funnel_stage),
    content_theme: c.content_theme || null,
    emotion_type: c.emotion_type || null,
    analyzed_at: new Date().toISOString()
  }));
  return { json: {
    is_influencer: true,
    handle: tp.handle,
    collabs, insights,
    creator_metrics_update: {
      ig_handle: tp.handle,
      total_brand_collaborations: data.collab_count_90d || collabs.length,
      unique_brands_count: new Set(collabs.map(c => c.brand_instagram).filter(Boolean)).size,
      top_brand_partners: data.top_brand_partners || []
    }
  } };
}

return { json: {
  is_influencer: false,
  handle: tp.handle,
  brand_metrics_update: {
    instagram_handle: tp.handle,
    influencer_collabs_90d: data.influencer_collabs || [],
    influencer_collab_count: data.total_collabs || 0,
    unique_influencer_partners: data.unique_influencer_count || 0,
    marketing_intensity: ['high','medium','low'].includes(String(data.marketing_intensity).toLowerCase())
      ? String(data.marketing_intensity).toLowerCase() : null
  }
} };
